"""Refresh skills/kalmia-setup/SKILL.md from the copy Kalmia's site serves.

The skill is generated by the site, so the site is the source of truth. When
the served copy differs from the one here, this writes it and bumps the patch
version in both plugin manifests, so installed plugins pick the change up.
Prints "changed" or "unchanged". Exits non-zero, changing nothing, if the
served file does not look like the skill.
"""

import json
import pathlib
import sys
import urllib.request

SOURCE = "https://www.kalmia.dev/skills/kalmia-setup/SKILL.md"
SKILL = pathlib.Path("skills/kalmia-setup/SKILL.md")
MANIFESTS = [pathlib.Path(".claude-plugin/plugin.json"), pathlib.Path(".cursor-plugin/plugin.json")]


def main() -> int:
    with urllib.request.urlopen(SOURCE, timeout=30) as response:
        served = response.read().decode("utf-8")

    # An error page or an empty body must never replace the skill.
    if not served.startswith("---\nname: kalmia-setup\n") or len(served) < 2000:
        print("The served file does not look like the kalmia-setup skill; leaving the repo as it is.", file=sys.stderr)
        return 1

    if SKILL.read_text(encoding="utf-8") == served:
        print("unchanged")
        return 0

    SKILL.write_text(served, encoding="utf-8")
    for path in MANIFESTS:
        manifest = json.loads(path.read_text(encoding="utf-8"))
        major, minor, patch = (int(part) for part in manifest["version"].split("."))
        manifest["version"] = f"{major}.{minor}.{patch + 1}"
        path.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print("changed")
    return 0


if __name__ == "__main__":
    sys.exit(main())
